"""Load / cache Transformers-native Qwen3-ASR (-hf) models."""

from __future__ import annotations

import logging
import threading
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .qwen3_hf_convert import (
    ensure_qwen3_hf_checkpoint,
    looks_like_hf_layout,
    looks_like_legacy_qwen_layout,
    missing_safetensors_shards,
    weights_have_thinker_prefix,
)
from .qwen3_hf_lora import attach_lora, looks_like_lora_adapter, resolve_lora_base_dir

_log = logging.getLogger("transub_engine.asr.qwen3_hf_model")

_MODEL_CACHE: dict[str, "Qwen3HfBundle"] = {}
_MODEL_LOCK = threading.Lock()


def _block_sklearn_if_scipy_blas_broken() -> None:
    """Keep Qwen3-ASR loading if sklearn/scipy is a broken robocopy.

    transformers.generation.candidate_generator imports sklearn.metrics.roc_curve
    whenever sklearn is *discoverable*. That pulls scipy.linalg._fblas. A pack
    copied without ``scipy.libs`` (OpenBLAS) then dies with WinError 126/127
    before the ASR weights load. Assisted-generation ROC is unused for Qwen3-ASR.
    """
    try:
        from scipy.linalg import _fblas  # noqa: F401

        return
    except Exception:
        pass
    try:
        from transformers.utils import import_utils as iu
    except Exception:
        return
    if getattr(iu, "_transub_block_sklearn", False):
        return
    orig = iu._is_package_available

    def _wrapped(pkg_name: str, return_version: bool = False):
        name = str(pkg_name or "").lower().replace("_", "-")
        if name in ("sklearn", "scikit-learn"):
            return (False, None) if return_version else (False, None)
        return orig(pkg_name, return_version=return_version)

    iu._is_package_available = _wrapped
    iu._transub_block_sklearn = True
    for attr in ("is_sklearn_available",):
        fn = getattr(iu, attr, None)
        if callable(fn) and hasattr(fn, "cache_clear"):
            try:
                fn.cache_clear()
            except Exception:
                pass
    _log.warning(
        "sklearn/scipy BLAS unavailable; Qwen3-ASR will load without sklearn "
        "(transformers assisted-generation ROC disabled)"
    )


@dataclass
class Qwen3HfBundle:
    """Processor + ASR model (+ optional ForcedAligner / LoRA)."""

    processor: Any
    model: Any
    device: str
    dtype: Any
    aligner_processor: Any | None = None
    aligner_model: Any | None = None
    is_lora: bool = False
    prefer_beam_search: bool = False

    @property
    def has_aligner(self) -> bool:
        return self.aligner_model is not None and self.aligner_processor is not None


def clear_hf_model_cache() -> int:
    with _MODEL_LOCK:
        n = len(_MODEL_CACHE)
        _MODEL_CACHE.clear()
    return n


def _enable_cuda_fast_matmul() -> None:
    try:
        from ..rocm_device import torch_is_rocm

        if torch_is_rocm():
            return
    except Exception:
        pass
    try:
        import torch

        if torch.cuda.is_available():
            torch.backends.cuda.matmul.allow_tf32 = True
            torch.backends.cudnn.allow_tf32 = True
    except Exception:
        pass


def device_map_for(device: str, *, torch_mod: Any | None = None) -> str:
    from ..device import resolve_torch_device_map

    return resolve_torch_device_map(device, torch_mod=torch_mod)


def _pick_dtype(torch: Any, device_map: str) -> Any:
    if not (str(device_map).startswith("cuda") or str(device_map).startswith("xpu")):
        return torch.float32
    # ROCm / RDNA4 (gfx1201) often trips bf16/fp16 kernels with hipErrorInvalidValue
    # on Qwen3 batch+beam; float32 is slower but reliable for consumer Radeon.
    try:
        from ..rocm_device import torch_is_rocm

        if torch_is_rocm():
            return torch.float32
    except Exception:
        pass
    # Ampere+ (sm>=8): bf16; older GPUs: fp16 (Turing lacks bf16 tensor cores).
    try:
        major, _minor = torch.cuda.get_device_capability(0)
        if int(major) >= 8:
            return torch.bfloat16
        return torch.float16
    except Exception:
        return torch.bfloat16


def _from_pretrained_kwargs(dtype: Any, device_map: str, *, with_attn: bool = True) -> dict[str, Any]:
    kw: dict[str, Any] = {"dtype": dtype, "device_map": device_map}
    if not with_attn:
        return kw
    try:
        from ..rocm_device import torch_is_rocm

        if torch_is_rocm():
            # SDPA / flash-attn style paths are a common source of hipErrorInvalidValue
            # on Windows ROCm + RDNA4; eager is slower but stable.
            kw["attn_implementation"] = "eager"
    except Exception:
        pass
    return kw


def _format_processor_import_error(err: BaseException) -> str:
    parts: list[str] = []
    seen: set[int] = set()
    cur: BaseException | None = err
    generic = "Are this object's requirements defined correctly?"
    while cur is not None and id(cur) not in seen and len(parts) < 5:
        seen.add(id(cur))
        text = str(cur).strip() or type(cur).__name__
        cause = cur.__cause__ or (
            cur.__context__ if cur.__context__ is not cur else None
        )
        if generic in text and cause is not None:
            cur = cause
            continue
        if text and text not in parts:
            parts.append(text)
        cur = cause
    return " ← ".join(parts) if parts else type(err).__name__


def _load_qwen3_processor(model_dir: str) -> Any:
    """Load Qwen3-ASR processor without AutoProcessor (avoids broken torchvision on ROCm)."""
    try:
        from transformers.models.qwen3_asr.processing_qwen3_asr import Qwen3ASRProcessor

        return Qwen3ASRProcessor.from_pretrained(model_dir)
    except Exception as err:
        chain = _format_processor_import_error(err).lower()
        if "torchvision" in chain or "autoprocessor" in chain:
            raise RuntimeError(
                "Qwen3-ASR 无法加载 Processor：引擎内 torchvision 与 ROCm PyTorch 不匹配。"
                "请在「环境检测」点一键修复（会重装或移除损坏的 torchvision），"
                "然后完全退出 Transub 再重试。"
                f"（{_format_processor_import_error(err)[:280]}）",
            ) from err
        raise


def _load_pretrained(cls: Any, path: str, **kwargs: Any) -> Any:
    try:
        return cls.from_pretrained(path, **kwargs)
    except (TypeError, ValueError) as err:
        if "attn_implementation" not in kwargs:
            raise
        _log.warning("Retrying from_pretrained without attn_implementation: %s", err)
        kwargs = dict(kwargs)
        kwargs.pop("attn_implementation", None)
        return cls.from_pretrained(path, **kwargs)


def _try_repair_hf_sidecars(path: Path, *, model_id: str | None = None) -> None:
    """Remap legacy thinker.* weights + refresh *-hf sidecars when needed."""
    try:
        conv = ensure_qwen3_hf_checkpoint(path, model_id=model_id)
        if conv.get("ok") and conv.get("converted"):
            _log.info("Repaired Qwen3 *-hf checkpoint under %s (%s)", path, conv.get("detail"))
        elif not conv.get("ok"):
            _log.warning(
                "Qwen3 checkpoint repair skipped/failed (%s); generate may use legacy chat path",
                conv.get("detail"),
            )
        if weights_have_thinker_prefix(path):
            raise RuntimeError(
                f"Qwen3 checkpoint at {path} still has legacy thinker.* weights after repair. "
                "Delete the folder and re-download the official *-hf pack "
                "(ForcedAligner: Qwen/Qwen3-ForcedAligner-0.6B-hf)."
            )
    except RuntimeError:
        raise
    except Exception as err:
        _log.warning("Qwen3 checkpoint repair error: %s", err)
        if weights_have_thinker_prefix(path):
            raise RuntimeError(
                f"Qwen3 checkpoint at {path} has legacy thinker.* weights and repair failed: {err}. "
                "Re-download the official *-hf model pack."
            ) from err


def load_qwen3_hf_bundle(
    asr_dir: Path | str,
    *,
    device: str = "auto",
    aligner_dir: Path | str | None = None,
    torch_mod: Any | None = None,
) -> Qwen3HfBundle:
    """Load Qwen3ASRProcessor + AutoModelForMultimodalLM (+ optional aligner / LoRA)."""
    import torch

    _block_sklearn_if_scipy_blas_broken()
    try:
        from transformers.models.auto.modeling_auto import AutoModelForMultimodalLM
        from transformers.models.auto.modeling_auto import AutoModelForTokenClassification
    except Exception:
        from transformers import (
            AutoModelForMultimodalLM,
            AutoModelForTokenClassification,
        )

    torch = torch_mod or torch
    asr_path = Path(asr_dir)
    align_path = Path(aligner_dir) if aligner_dir else None
    is_lora = looks_like_lora_adapter(asr_path)
    base_path = resolve_lora_base_dir(asr_path) if is_lora else asr_path

    if not is_lora:
        _try_repair_hf_sidecars(asr_path, model_id=asr_path.name)
    else:
        _try_repair_hf_sidecars(base_path, model_id=base_path.name)
    if align_path is not None and align_path.is_dir():
        _try_repair_hf_sidecars(align_path, model_id=align_path.name)

    if is_lora:
        if not looks_like_hf_layout(base_path) and not (base_path / "config.json").is_file():
            raise RuntimeError(
                f"Qwen3 LoRA base at {base_path} is not Transformers-native (-hf). "
                "Re-download qwen3-asr-1.7b."
            )
    elif not looks_like_hf_layout(asr_path) and not looks_like_legacy_qwen_layout(asr_path):
        raise RuntimeError(
            f"Qwen3-ASR model at {asr_path} is not Transformers-native (-hf): "
            "missing tokenizer.json / config. Delete the folder and download again."
        )
    elif not (asr_path / "config.json").is_file():
        raise RuntimeError(
            f"Qwen3-ASR model at {asr_path} is not Transformers-native (-hf): "
            "missing config.json. Delete the folder and download again."
        )

    device_map = device_map_for(device, torch_mod=torch)
    dtype = _pick_dtype(torch, device_map)
    key = f"{asr_path}|{base_path}|{align_path or ''}|{device_map}|{dtype}|lora={is_lora}"

    with _MODEL_LOCK:
        cached = _MODEL_CACHE.get(key)
        if cached is not None:
            return cached
        if str(device_map).startswith("cuda"):
            _enable_cuda_fast_matmul()

        # Processor: prefer adapter dir (ships tokenizer/processor), else base.
        proc_root = asr_path if (asr_path / "tokenizer.json").is_file() else base_path
        _log.info(
            "Loading Qwen3-ASR -hf from %s%s (device_map=%s)",
            base_path,
            f" + LoRA {asr_path.name}" if is_lora else "",
            device_map,
        )
        processor = _load_qwen3_processor(str(proc_root))
        missing = missing_safetensors_shards(base_path)
        if missing and not (base_path / "model.safetensors").is_file():
            raise FileNotFoundError(
                f"Qwen3-ASR 权重分片不完整，缺少 {', '.join(missing[:8])}。"
                "请重新下载该模型（已下好的分片会续传，不必整包重来）。"
            )
        load_kw = _from_pretrained_kwargs(dtype, device_map, with_attn=True)
        model = _load_pretrained(AutoModelForMultimodalLM, str(base_path), **load_kw)
        if is_lora:
            model = attach_lora(model, asr_path)
        model.eval()

        aligner_processor = None
        aligner_model = None
        if align_path is not None and align_path.is_dir():
            _log.info("Loading Qwen3 ForcedAligner -hf from %s", align_path)
            aligner_processor = _load_qwen3_processor(str(align_path))
            align_kw = _from_pretrained_kwargs(dtype, device_map, with_attn=False)
            aligner_model = _load_pretrained(
                AutoModelForTokenClassification,
                str(align_path),
                **align_kw,
            )
            aligner_model.eval()

        use_beam = bool(is_lora)
        try:
            from ..rocm_device import torch_is_rocm

            if torch_is_rocm():
                use_beam = False
                _log.info(
                    "Qwen3-ASR ROCm: dtype=float32, attn=eager, greedy decode "
                    "(beam/batch bf16 often hits hipErrorInvalidValue on RDNA4)"
                )
        except Exception:
            pass

        bundle = Qwen3HfBundle(
            processor=processor,
            model=model,
            device=str(device_map),
            dtype=dtype,
            aligner_processor=aligner_processor,
            aligner_model=aligner_model,
            is_lora=is_lora,
            prefer_beam_search=use_beam,
        )
        _MODEL_CACHE[key] = bundle
        return bundle
